import Foundation

func planUITokens(root: URL) throws -> Data {
    let data = try Data(contentsOf: root.appending(path: "_design/canvas/ds/chronoflow/tokens.json"))
    let json = try JSONSerialization.jsonObject(with: data) as! [String: Any]
    var code =
        "// Generated by Tools/TokenGen from tokens.json. Do not edit.\nimport Foundation\nnonisolated public enum PlanUITokens {\n"
    for group in ["spacing", "radius"] {
        for token in (json[group] as! [String: Any])["tokens"] as! [[String: Any]] {
            let value = token["value"] as! String
            if value.hasSuffix("px") {
                code += "public static var \(camelCase(token["name"] as! String)): CGFloat { \(value.dropLast(2)) }\n"
            }
        }
    }
    let rowBoard = try String(
        contentsOf: root.appending(path: "_design/canvas/TodayRowStates.dc.html"), encoding: .utf8)
    let marked = try captures(#"opacity: ([\d.]+);"#, in: rowBoard)[0]
    code += "public static var markedOpacity: Double { \(marked) }\n"
    let patterns =
        try JSONSerialization.jsonObject(
            with: Data(contentsOf: root.appending(path: "Tools/TokenGen/PlanUI.source.json"))) as! [String: Any]
    for key in patterns.keys.sorted() where key != "source" {
        code +=
            "public static var \(key): \(["Opacity", "Ratio", "Saturation", "Duration"].contains(where: key.hasSuffix) ? "Double" : "CGFloat") { \(patterns[key]!) }\n"
    }
    code += "}\nextension Typography {\n"
    for group in (json["type"] as! [String: Any])["groups"] as! [[String: Any]] {
        for style in group["styles"] as! [[String: Any]] {
            let size = Double((style["fontSize"] as! String).dropLast(2))!
            let line =
                (style["lineHeight"] as? String).flatMap { Double($0.dropLast(2)) }
                ?? size * (style["lineHeight"] as! Double)
            let weight = style["fontWeight"] as! Int
            let face =
                group["family"] as! String == "display"
                ? "fraunces400Opsz\(size >= 40 ? 48 : size >= 26 ? 32 : 20)" : "figtree\(weight)"
            let tracking = (style["letterSpacing"] as? String).flatMap { Double($0.dropLast(2)) }.map { $0 * size } ?? 0
            code +=
                "public static var \(camelCase("screen-" + (style["name"] as! String))): Style { Style(face: .\(face), size: \(size), lineHeight: \(line), tracking: \(tracking), relativeTo: .body) }\n"
        }
    }
    code += """
        public static var walkthroughBody: Style {
            Style(face: .figtree500, size: screenBodyLg.size, lineHeight: screenBodyLg.lineHeight,
                  tracking: screenBodyLg.tracking, relativeTo: screenBodyLg.relativeTo)
        }
        public static var wizardAirport: Style {
            Style(face: .figtree600, size: PlanUITokens.wizardAirportFontSize, lineHeight: PlanUITokens.wizardAirportLineHeight,
                  tracking: screenBody.tracking, relativeTo: .headline)
        }
        public static var wizardAirportPlaceholder: Style {
            Style(face: .figtree400, size: PlanUITokens.wizardAirportFontSize, lineHeight: PlanUITokens.wizardAirportLineHeight,
                  tracking: screenBody.tracking, relativeTo: .headline)
        }
        public static var wizardRow: Style {
            Style(face: .figtree400, size: PlanUITokens.wizardRowFontSize, lineHeight: PlanUITokens.wizardRowLineHeight,
                  tracking: screenBody.tracking, relativeTo: .body)
        }
        public static var wizardButton: Style {
            Style(face: .figtree600, size: PlanUITokens.wizardRowFontSize, lineHeight: PlanUITokens.wizardRowLineHeight,
                  tracking: screenBody.tracking, relativeTo: .body)
        }
        public static var wizardSubtitle: Style {
            Style(face: .figtree400, size: screenBodyLg.size, lineHeight: PlanUITokens.wizardRowLineHeight,
                  tracking: screenBody.tracking, relativeTo: .body)
        }
        public static var wizardHint: Style {
            Style(face: .figtree400, size: PlanUITokens.wizardHintFontSize, lineHeight: PlanUITokens.wizardHintLineHeight,
                  tracking: screenBody.tracking, relativeTo: .caption)
        }
        public static var wizardChoice: Style {
            Style(face: .figtree600, size: PlanUITokens.wizardChoiceFontSize, lineHeight: PlanUITokens.wizardChoiceLineHeight,
                  tracking: screenBody.tracking, relativeTo: .headline)
        }
        public static var wizardRoute: Style {
            Style(face: .figtree600, size: PlanUITokens.wizardRouteFontSize, lineHeight: PlanUITokens.wizardRouteLineHeight,
                  tracking: screenBody.tracking, relativeTo: .subheadline)
        }
        }

        """
    return try formattedSwift(code, root: root)
}
